"""Report verified experimental results and append without rewriting prior science."""
import sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'work/sleep_frailty_ml_v9'))
from v9_common import *
DEST=ROOT/'outputs/sleep_frailty_ml_next';FINAL=DEST/'validation';MANUSCRIPT=ROOT/'outputs/nhanes_manuscript_audit'

def percentage(value):return f'{100*value:.2f}%'

def main():
    assert_previous_sources();audit=json.loads((FINAL/'reserved_results_independent_audit.json').read_text());assert audit['passed'];r=json.loads((FINAL/'reserved_outcome_evaluation.json').read_text());assert sha(FINAL/'reserved_outcome_evaluation.json')==audit['original_result_sha256'];development=json.loads((DEST/'coverage_development_assessment.json').read_text());selected=development['selected'];settings=json.loads((FINAL/'final_settings_lock.json').read_text());assert not (FINAL/'manuscript_integration_receipt.json').exists()
    lines=['# Cell matched molecular prediction and reserved experimental validation','',
           'The response model predicts the magnitude of DNA effects measured in laboratory reporter experiments. The reserved results below determine whether it improves on typical measured effects and whether its uncertainty is useful. Human insomnia and frailty risk are separate outcomes.','',
           '## Experimental data and model fitting','',
           'The locked development expansion added 41,451 original absolute fitted log2 effect measurements from 13,817 OL27 DNA designs measured in HepG2, K562 and SK-N-SH, giving 654,612 development observations in total. Each connected genomic and shared-DNA component remained in one partition. Original arrays and partitions were preserved as exact prefixes, and all OL33-connected and blood-test regions stayed outside fitting. No detection, significance, activity, effect-size or standard-error cutoff selected examples. Original unsigned targets were retained; unproven coefficient signs and allele activity targets were left missing.','',
           'Three fixed author-trained DNA models supplied summaries of each complete source reference/alternate sequence. A small head with 8,461 trainable parameters learned effect magnitude by backpropagation; the author models stayed fixed. One author model per cell was used, rather than the full published ensemble. The selected common epoch was '+str(selected['common_epoch'])+', with mean development error improvement of '+percentage(selected['mean_source_line_median_error_skill'])+' over training-only cell/culture medians across seven omitted publications. Whole Siraj omission removed its old and new libraries together. These selected development results do not establish transfer to new experiments.','',
           'Final three-seed ensembles used identical observations, shared initial parameters, batches, losses and update counts with and without three added AVI inputs. AVI is the designated permissive composite score, which includes AlphaGenome-related information and other annotations. It was used as an input only. Its contribution cannot be attributed uniquely to AlphaGenome, and absence from every AVI/AlphaGenome training resource has not been established.','',
           '## Reserved experimental tests','',
           'The independent-publication blood test contained 236 physically verified designs, representing 49 distinct variants in 46 source regions, with measurements in four cell models. Exact K562 was the primary known-line test; HL60, CHRF and THP1 remained unfamiliar-line diagnostics with no authorized predictions. The held OL33 library supplied 39,723 measurements of 13,241 designs in three known lines. It comes from the existing Siraj publication and lab, so it is not independent-publication or donor replication. A further 1,932 OL27 reserved measurements are descriptive.','',
           'Full actual 148 bp blood and 200 bp library sequences were used without padding or invented genomic context. Canonical genomic neighborhoods and literal shared DNA were screened against the published libraries covering all actual author pretraining sequences. Unmapped source coordinates limit wider-neighborhood claims. Published paired GLM coefficients and source count aggregates were checked, but the original raw barcode pipeline and GLM were not independently rebuilt.','',
           'Both ensembles, uncertainty models, acceptance rules and predictions were frozen before the numeric target join. Accuracy used absolute original tile-level Log2Skew. The primary error and correlation measures give equal weight to cell lines; correlations are computed within each line before averaging. Intervals below are empirical targets, with 2,000 paired bootstrap samples of fixed one-megabase windows for accuracy comparisons. These windows are not ancestry-specific LD blocks.','',
           '| Test | Input | Mean absolute error | Typical effect error | Relative error improvement | Within line correlation | Interval coverage | Accepted before outcomes |','| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    table=[]
    for test in ['blood_K562','OL33_three_known_lines']:
        for arm in ['sequence','AVI']:
            a=r['primary_accuracy'][arm][test];c=r['confidence'][arm][test];name='Independent blood K562' if test=='blood_K562' else 'Held OL33 library';rho=a['macro_within_cell_line_Spearman'];rho_text=f'{rho:.4f}' if rho is not None else 'undefined'
            lines.append(f"| {name} | {arm} | {a['macro_MAE']:.6f} | {a['macro_training_line_or_cell_median_MAE']:.6f} | {percentage(a['relative_MAE_gain_vs_line_median'])} | {rho_text} | {percentage(c['observed_coverage'])} | {c['accepted_rows']} / {c['rows']} |")
            table.append({'test':test,'arm':arm,**{k:a[k] for k in ['rows','macro_MAE','macro_training_line_or_cell_median_MAE','relative_MAE_gain_vs_line_median','gain_vs_line_95CI','macro_within_cell_line_Spearman','all_accuracy_gates_pass']},**{k:c[k] for k in ['observed_coverage','accepted_rows','accepted_windows','useful_confident_answers_pass']}})
    decision=r['AVI_decision'];lines+=['','Negative improvement means worse prediction than the typical-effect baseline. Complete confidence intervals, per-line results and direct nearby/cell difference comparisons are retained in reserved_outcome_evaluation.json. The independent audit separately reconstructed all original targets and primary error, correlation, coverage and bootstrap results; pair point estimates were independently checked, but pair confidence intervals were not independently replayed.','',
           '## Confidence and nearby cell differences','',
           'Development checks excluded each outer publication from base fitting, confidence fitting and interval scaling. Confidence training used other publications original calibration regions from that same omitted-source base model. The original source-protected Siraj check still achieved only 76.43% overall coverage, with all cases withheld. Final scaling used conservative source-specific residual quantiles and absolute error floors. Exact unfamiliar lines, unusual inputs and cases without sufficient predicted benefit or narrow uncertainty were withheld. High coverage achieved by broad intervals, or withholding every case, is not useful prediction.','']
    for arm in ['sequence','AVI']:
        p=r['paired_difference_results'][arm]['OL33_three_known_lines'];lines.append(f"{arm}: the held OL33 test provided {p['local'].get('pairs',0):,} nearby comparisons and {p['cross'].get('pairs',0):,} comparisons of the same physical design across cell lines. Direct difference error, median-difference baselines, within-fixed-cell-pair correlations and interval coverage are reported separately. A pooled difference correlation alone does not establish variant-specific cell effects.")
        lines.append('')
    lines+=['## AlphaGenome related input decision','',
            f"Retain AVI under the prespecified tests: **{decision['retain_AVI']}**. Both primary relative-gain and confidence-interval gates passed: **{decision['both_primary_relative_gain_and_CI_gates_pass']}**. Both absolute accuracy gates passed: **{decision['both_primary_absolute_accuracy_gates_pass']}**. Local OL33 confirmation was sufficiently large: **{decision['OL33_local_confirmation_sufficient']}**, and ranking preservation passed: **{decision['OL33_local_ranking_preserved']}**.",'',
            '## Manuscript readiness','',
            'Completed evidence comprises source and allele/physical-DNA audits, reproducible training, matched added-input testing, source-protected confidence checks and reserved experimental evaluation with an independent numerical audit. Development gains remain exploratory; original V7 and V9 adverse tests retain their original status. The experimental model supplies no independent person-level genetic-score validation, sleep/fatigue-excluded frailty GWAS, genetic correlation, disease causation or causal variant-to-gene proof. The Nature Communications genetic manuscript remains unready while those scientific validation gaps remain.','',
            'The reserved outcomes are now revealed and cannot be reused as untouched tests of a subsequently changed model. Any further model development must preserve these findings and obtain new appropriate validation before claiming improved transfer.','',
            'Primary sources: [Siraj et al.](https://doi.org/10.1038/s41586-026-10121-6), [Tardaguila et al.](https://doi.org/10.1016/j.celrep.2026.116937), and the pinned author pretrained DNA model/library source records retained in next_source_screen.']
    supplement=MANUSCRIPT/'supplement/molecular_prediction_cell_matched.md';supplement.write_text('\n'.join(lines)+'\n');write_csv(FINAL/'manuscript_primary_results.csv',table)
    model_pass={arm:all(a['all_accuracy_gates_pass'] for a in r['primary_accuracy'][arm].values()) for arm in ['sequence','AVI']};confidence_pass={arm:all(c['useful_confident_answers_pass'] for c in r['confidence'][arm].values()) for arm in ['sequence','AVI']}
    paragraphs=['','## Cell matched molecular prediction and reserved experimental validation','',
                f"A separate development expansion added 41,451 paired reporter measurements from 13,817 OL27 DNA designs in three cell models, preserving the earlier analyses and all original data partitions. Three frozen author-trained DNA models supplied features for a small regression head. One common epoch selected across seven omitted sources improved development error over training-only cell/culture medians by {percentage(selected['mean_source_line_median_error_skill'])}; this is selected development evidence. All OL33-connected and independent blood-test regions remained outside fitting.",'',
                'The reserved blood experiment comprised 236 designs representing 49 variants, with K562 as the primary known-line comparison; unfamiliar blood lines remained diagnostic. A second test comprised 39,723 OL33 measurements across three known lines from the same Siraj paper and lab. Full source DNA, genomic build and overlap checks preceded fitting, and models, confidence rules and both added-input arms were frozen before target join.']
    for test in ['blood_K562','OL33_three_known_lines']:
        a=r['primary_accuracy']['sequence'][test];c=r['confidence']['sequence'][test];name='independent blood K562' if test=='blood_K562' else 'held OL33 library';paragraphs+=['',f"In the {name} test, sequence-only mean absolute error was {a['macro_MAE']:.6f} versus {a['macro_training_line_or_cell_median_MAE']:.6f} for the training-only culture median, a relative improvement of {percentage(a['relative_MAE_gain_vs_line_median'])}. Nominal 90% intervals covered {percentage(c['observed_coverage'])}; {c['accepted_rows']} cases met the input policy before outcomes were joined. Full accuracy gates passed: **{a['all_accuracy_gates_pass']}**; useful confidence gates passed: **{c['useful_confident_answers_pass']}**."]
    paragraphs+=['',f"The matched permissible composite AVI input met the prespecified retention gates: **{decision['retain_AVI']}**. This comparison cannot attribute an effect uniquely to AlphaGenome. Complete negative and positive comparisons, interval size, cell/nearby differences and audit limitations are in the [cell matched molecular supplement](supplement/molecular_prediction_cell_matched.md). This laboratory benchmark supplies no human sleep/frailty score validation or causal gene evidence. All original genetic and NHANES observational results remain unchanged."]
    ms=MANUSCRIPT/'manuscript_with_nhanes.md';before=ms.read_text();heading='## Cell matched molecular prediction and reserved experimental validation';assert heading not in before;old_hash=sha(ms);ms.write_text(before+'\n'.join(paragraphs)+'\n');after=ms.read_text();assert after.startswith(before)
    readiness={'measured_effect_size_prediction':{'implementation_complete':True,'fresh_accuracy_pass_by_arm':model_pass},
               'nearby_and_cell_differences':{'held_library_test_completed':True,'independent_blood_cell_interaction_validation':False,'pair_CIs_independently_replayed':False},
               'confidence_across_experiments':{'source_protected_checks_complete':True,'useful_fresh_confidence_pass_by_arm':confidence_pass},
               'AlphaGenome_related_added_input':{'matched_experiment_complete':True,'retain_AVI':decision['retain_AVI'],'unique_AlphaGenome_attribution':False},
               'human_genetic_score_validation':False,'scientific_objective_complete':False,'Nature_Communications_genetic_manuscript_ready':False,
               'new_outcomes_now_revealed':True,'original_scientific_results_preserved':True,'authorized_project_answers':0}
    write_json(FINAL/'readiness_assessment.json',readiness)
    write_json(FINAL/'manuscript_integration_receipt.json',{'entire_previous_manuscript_prefix_preserved':True,'previous_manuscript_sha256':old_hash,'previous_character_count':len(before),
              'updated_manuscript_sha256':sha(ms),'supplement_sha256':sha(supplement),'verified_result_sha256':sha(FINAL/'reserved_outcome_evaluation.json'),'independent_result_audit_sha256':sha(FINAL/'reserved_results_independent_audit.json')})
    text=['ADDITIONAL FREE DATA AND MODEL UPDATE','',f"Added 41,451 measured DNA effects; total 654,612 observations. Selected development error gain: {percentage(selected['mean_source_line_median_error_skill'])} over typical-effect predictions. This small development gain is not proof of usefulness.",'']
    for test in ['blood_K562','OL33_three_known_lines']:
        a=r['primary_accuracy']['sequence'][test];c=r['confidence']['sequence'][test];text.append(f"{test}: error improvement {percentage(a['relative_MAE_gain_vs_line_median'])}; 90%-target interval coverage {percentage(c['observed_coverage'])}; pretest accepted {c['accepted_rows']}/{c['rows']}; accuracy gates {a['all_accuracy_gates_pass']}; useful confidence gates {c['useful_confident_answers_pass']}.")
    text+=['',f"Keep the added AVI scores: {decision['retain_AVI']}. All original adverse tests are preserved. New target joins and primary results were independently checked.",'','This is a laboratory DNA-effect model, not a predictor of insomnia or frailty in people. No project genetic rankings are authorized. The full scientific objective and Nature Communications genetic readiness remain incomplete.']
    (DEST/'PLAIN_LANGUAGE_PROGRESS.txt').write_text('\n'.join(text)+'\n');assert_previous_sources();print('\n'.join(text),flush=True)

if __name__=='__main__':main()
